        for j in [0,w-1]:
            if g[i][j]!=0 and not seen[i][j]:
                seen[i][j]=True; stack.append((i,j))
    for j in range(w):
        for i in [0,h-1]:
            if g[i][j]!=0 and not seen[i][j]:
                seen[i][j]=True; stack.append((i,j))
    while stack:
        i,j=stack.pop()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            x,y=i+dx,j+dy
            if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]!=0:
                seen[x][y]=True; stack.append((x,y))
    out=g.copy()
    for i in range(h):
        for j in range(w):
            if not seen[i][j] and g[i][j]!=0:
                out[i][j]=4
    return out.tolist()
